sql.where:
p.tradeStatus NOT IN ('숨기기', '임시저장')


	AND p.tradeStatus NOT IN ('판매완료', '예약중')



	AND p.price >= #{priceMin}



	AND p.price <= #{priceMax}



	AND p.regionIdx = #{userRegionIdx}



	AND (
		p.title LIKE '%' || #{keyword} || '%' 
		OR p.content LIKE '%' || #{keyword} || '%'
		OR EXISTS (
			SELECT 1 FROM productTag pt
			JOIN tag t ON pt.tagIdx = t.tagIdx
			WHERE pt.productIdx = p.productIdx AND t.tagName = #{keyword}
		)
	)



	AND p.categoryIdx = #{categoryIdx}

mapper.insert:
INSERT INTO productImages (
    productIdx, imgOrder, originalName, saveName, imgUrl
) VALUES (
    #{productIdx}, #{imgOrder}, #{originalName}, #{saveName}, #{imgUrl}
)

mapper.select:
SELECT saveName 
FROM productImages 
WHERE productIdx = #{productIdx} AND imgOrder = #{imgOrder}

SELECT NVL(MAX(imgOrder), 0) 
FROM productImages 
WHERE productIdx = #{productIdx}
